mapper.select:
SELECT UserID, Nickname, Handle, ProfileImage
FROM T_TRACE_USERS
WHERE UserID NOT IN (
  SELECT FollowingID FROM T_TRACE_FOLLOWS WHERE FollowerID = #{userId}
)
AND UserID != #{userId}
FETCH FIRST 3 ROWS ONLY

SELECT * FROM T_TRACE_CHATROOMS
WHERE ChatRoomID IN (
    SELECT ChatRoomID
    FROM T_TRACE_CHAT_PARTICIPANTS
    WHERE UserID = #{userId}
)

SELECT USERID, USERNAME, HANDLE, EMAIL, PASSWORD, NICKNAME, PROFILEIMAGE, USERTYPE, JOINDATE
FROM T_TRACE_USERS
WHERE USERID = #{userId}

SELECT USERID, USERNAME, HANDLE, EMAIL, PASSWORD, NICKNAME, PROFILEIMAGE, USERTYPE, JOINDATE
FROM T_TRACE_USERS
WHERE HANDLE = #{handle}

mapper.update:
UPDATE T_TRACE_USERS
SET USERNAME = #{username},
    HANDLE   = #{handle},
    EMAIL    = #{email}
WHERE USERID = #{userId}

UPDATE T_TRACE_USERS
SET PASSWORD = #{password}
WHERE USERID = #{userId}

mapper.select:
SELECT COUNT(*)
FROM T_TRACE_USERS
WHERE HANDLE = #{handle}
  AND USERID != #{userId}

SELECT COUNT(*) FROM T_TRACE_USERS
WHERE EMAIL = #{email}
  AND USERID != #{userId}
